  case 1: args = ["\"hello, world\",x"] (expected WITHHELD)
  case 2: args = [""] (expected WITHHELD)
  case 3: args = ["\"a\"\"b\""] (expected WITHHELD)
  case 4: args = ["1,,3"] (expected WITHHELD)
